    public function contact(Request $request){

        $data=$request->validate([
            'name' => 'required',
            'email' => 'required',
            'subject' => 'required',
            'message' => 'required',
        ]);

        ContactUs::create($data);
        $url=route('front.contactUs');
        return response()->json(['status'=>true,'msg'=>'Your message has been sent successfully!', 'url'=>$url]);

    }
    
